src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny)); q.append((nx,ny))
            sides = set()
            for x, y in cells:
                if x == 0: sides.add('top')
                if x == h-1: sides.add('bottom')
                if y == 0: sides.add('left')
                if y == w-1: sides.add('right')
            comps.append((color, cells, sides))
    corners = ({'top','left'}, {'top','right'}, {'bottom','left'}, {'bottom','right'})
    marker = next((comp for comp in comps if any(corner <= comp[2] for corner in corners)), None)
    if marker is None:
        marker = max(comps, key=lambda comp: max(r for r,c in comp[1])-min(r for r,c in comp[1])+max(c for r,c in comp[1])-min(c for r,c in comp[1]))
    target = max((comp for comp in comps if comp is not marker), key=lambda comp: len(comp[1]))
    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = marker[0]
    return out
'''
